'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let pos = 0;
const n = input[pos++];
const graph = Array.from({ length: n }, () => []);

for (let i = 0; i < n - 1; i++) {
  const x = input[pos++] - 1;
  const y = input[pos++] - 1;
  graph[x].push(y);
  graph[y].push(x);
}

function traverse(start) {
  const dist = new Int32Array(n);
  dist.fill(-1);
  const parent = new Int32Array(n);
  parent.fill(-1);

  const queue = new Int32Array(n);
  let head = 0;
  let tail = 0;
  queue[tail++] = start;
  dist[start] = 0;
  let farthest = start;

  while (head < tail) {
    const u = queue[head++];
    if (dist[u] > dist[farthest]) farthest = u;

    for (const v of graph[u]) {
      if (dist[v] === -1) {
        dist[v] = dist[u] + 1;
        parent[v] = u;
        queue[tail++] = v;
      }
    }
  }

  return { farthest, parent };
}

const endpointA = traverse(0).farthest;
const result = traverse(endpointA);
const endpointB = result.farthest;

const path = [];
for (let u = endpointB; u !== -1; u = result.parent[u]) path.push(u);
path.reverse();

const diameter = path.length - 1;
let ways = 0;

if (diameter % 2 === 0) {
  const center = path[diameter / 2];
  const radius = diameter / 2;
  let total = 0;
  let sumSquares = 0;

  for (const neighbor of graph[center]) {
    let count = 0;
    const stack = [[neighbor, center, 1]];

    while (stack.length) {
      const [u, parent, depth] = stack.pop();
      if (depth === radius) {
        count++;
        continue;
      }
      for (const v of graph[u]) {
        if (v !== parent) stack.push([v, u, depth + 1]);
      }
    }

    total += count;
    sumSquares += count * count;
  }

  ways = (total * total - sumSquares) / 2;
} else {
  const radius = (diameter - 1) / 2;
  const leftCenter = path[radius];
  const rightCenter = path[radius + 1];

  function countSide(start, blocked) {
    let count = 0;
    const stack = [[start, blocked, 1]];

    while (stack.length) {
      const [u, parent, depth] = stack.pop();
      if (depth === radius) {
        count++;
        continue;
      }
      for (const v of graph[u]) {
        if (v !== parent) stack.push([v, u, depth + 1]);
      }
    }

    return count;
  }

  ways = countSide(leftCenter, rightCenter) * countSide(rightCenter, leftCenter);
}

console.log(`${diameter + 1}\n${ways}`);
